  "implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    # DP table: dp[i][w] = max score using first i items, weight <= w
    dp = [[0.0] * (budget + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        w_i = lengths[i - 1]
        v_i = scores[i - 1]
        for w in range(budget + 1):
            if w_i <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - w_i] + v_i)
            else:
                dp[i][w] = dp[i - 1][w]
    # Reconstruct selected indices
    w = budget
    selected = []
    for i in range(n, 0, -1):
        if dp[i][w] != dp[i - 1][w]:
            selected.append(i - 1)
            w -= lengths[i - 1]
    selected.reverse()
    tokens_used = sum(lengths[i] for i in selected)
    total_score = sum(scores[i] for i in selected)
    return {
        'selected_indices': selected,
        'tokens_used': tokens_used,
        'total_score': total_score
    }"
}
